"""Regex compatibility layer.

Translates Rust `regex` crate syntax to Python `re` and provides matching
with Rust-like semantics (e.g. empty-match handling) as far as observed.

Owned by: regex agent. Interface contract used by engine.py:

    compile_pattern(pattern: str, literal: bool) -> CompiledPattern
    CompiledPattern.finditer(text: str) -> Iterator[re.Match-like]
    CompiledPattern.rust_error -> None

    class RegexBuildError(Exception): message is the human description that
        engine prints after "Invalid regex: ".
"""

import re


class RegexBuildError(Exception):
    pass


def _translate(pattern: str) -> str:
    """Translate rust-regex syntax to Python re syntax. Minimal for now."""
    # Rust allows (?<name>...) in addition to (?P<name>...)
    out = []
    i = 0
    n = len(pattern)
    while i < n:
        if pattern.startswith("(?<", i) and not pattern.startswith("(?<=", i) and not pattern.startswith("(?<!", i):
            out.append("(?P<")
            i += 3
        else:
            out.append(pattern[i])
            i += 1
    return "".join(out)


class CompiledPattern:
    def __init__(self, pattern: str, literal: bool):
        self.pattern = pattern
        self.literal = literal
        if literal:
            self.re = None
        else:
            try:
                self.re = re.compile(_translate(pattern))
            except re.error as e:
                raise RegexBuildError(str(e))

    def finditer(self, text: str):
        if self.literal:
            start = 0
            pat = self.pattern
            if pat == "":
                return
            while True:
                idx = text.find(pat, start)
                if idx < 0:
                    return
                yield _LiteralMatch(idx, idx + len(pat), text)
                start = idx + len(pat)
        else:
            # Rust regex semantics: skip empty match that starts exactly at the
            # end of the previous match; advance one char after an empty match.
            prev_end = -1
            pos = 0
            n = len(text)
            while pos <= n:
                m = self.re.search(text, pos)
                if not m:
                    return
                s, e = m.span()
                if s == e and s == prev_end:
                    # empty match adjacent to previous match end: skip it
                    pos = s + 1
                    continue
                prev_end = e
                yield m
                if s == e:
                    pos = e + 1
                else:
                    pos = e


class _LiteralMatch:
    """Duck-typed stand-in for re.Match for literal searches."""

    def __init__(self, s, e, text):
        self._s = s
        self._e = e
        self._text = text

    def span(self, group=0):
        return (self._s, self._e)

    def group(self, *args):
        if not args or args == (0,):
            return self._text[self._s:self._e]
        raise IndexError("no such group")

    def groupdict(self):
        return {}

    @property
    def re(self):
        return None

    @property
    def string(self):
        return self._text


def compile_pattern(pattern: str, literal: bool = False) -> CompiledPattern:
    return CompiledPattern(pattern, literal)

