Owned by: german agent. Contract:

    apply(text: str, naive: bool, prefer_original: bool) -> str

Replaces ASCII spellings of German Umlauts (ae, oe, ue) and Eszett (ss)
with native Unicode where the result is a legal German word (unless naive).
"""

# Probed word results: maps input word -> output word for default mode.
# PLACEHOLDER - to be completed by probing the reference binary.
KNOWN = {
    "Abenteuergruesse": "Abenteuergrüße",
    "Bruecken": "Brücken",
    "Muenchen": "München",
    "Strasse": "Straße",
    "Busse": "Buße",
    "Koeffizienten": "Koeffizienten",
}

_NAIVE_SUBS = [
    ("Ae", "Ä"), ("Oe", "Ö"), ("Ue", "Ü"),
    ("ae", "ä"), ("oe", "ö"), ("ue", "ü"),
    ("AE", "Ä"), ("OE", "Ö"), ("UE", "Ü"),
    ("ss", "ß"), ("SS", "ß"),
]


def _naive_word(word: str) -> str:
    for src, dst in _NAIVE_SUBS:
        word = word.replace(src, dst)
    return word


def apply(text: str, naive: bool = False, prefer_original: bool = False) -> str:
    import re

    def sub_word(m):
        w = m.group(0)
        if naive:
            return _naive_word(w)
        if prefer_original and w in KNOWN_PREFER_ORIGINAL_KEEP:
            return w
        return KNOWN.get(w, w)

    return re.sub(r"\w+", sub_word, text, flags=re.UNICODE)


KNOWN_PREFER_ORIGINAL_KEEP = {
    "Busse",
}

