"""Text transformation actions.

Owned by: actions agent. Contract (all operate on plain strings):

    upper(text) -> str
    lower(text) -> str
    titlecase(text) -> str
    normalize(text) -> str          # NFD, strip marks
    substitute_template(template, match) -> str   # $1, $NAME, ${NAME}, $$, $0
        raises ActionError on undefined variable

Application order (observed): replacement, german, symbols, upper, lower,
titlecase, normalize.
"""

import unicodedata


class ActionError(Exception):
    pass


def upper(text: str) -> str:
    # Observed: full Unicode uppercase, EXCEPT sharp-s maps to capital ẞ.
    return text.upper().replace("SS", "SS")  # placeholder, agent refines


def lower(text: str) -> str:
    return text.lower()


def titlecase(text: str) -> str:
    # Observed: word = [A-Za-z0-9_]+ runs; first char uppercased, rest kept?
    out = []
    at_word_start = True
    for ch in text:
        if ch.isalnum() or ch == "_":
            if at_word_start:
                out.append(ch.upper())
            else:
                out.append(ch)
            at_word_start = False
        else:
            out.append(ch)
            at_word_start = True
    return "".join(out)


def normalize(text: str) -> str:
    return "".join(
        ch for ch in unicodedata.normalize("NFD", text) if not unicodedata.combining(ch)
    )


def substitute_template(template: str, match) -> str:
    """Expand $-variables in replacement template against a regex match."""
    out = []
    i = 0
    n = len(template)
    while i < n:
        ch = template[i]
        if ch != "$":
            out.append(ch)
            i += 1
            continue
        if i + 1 < n and template[i + 1] == "$":
            out.append("$")
            i += 2
            continue
        # parse name: ${...} or $name / $number
        j = i + 1
        braced = False
        if j < n and template[j] == "{":
            braced = True
            k = template.find("}", j)
            if k < 0:
                out.append("$")
                i += 1
                continue
            name = template[j + 1:k]
            j = k + 1
        else:
            k = j
            while k < n and (template[k].isalnum() or template[k] == "_"):
                k += 1
            if k == j:
                out.append("$")
                i += 1
                continue
            name = template[j:k]
            j = k
        # resolve
        try:
            if name.isdigit():
                val = match.group(int(name))
            else:
                val = match.group(name)
        except (IndexError, KeyError):
            raise ActionError(
                "Error in an action: Action failed in replacement: Error in "
                f"variable expressions: Undefined variable, unable to substitute: '{name}'"
            )
        if val is None:
            val = ""
        out.append(val)
        i = j
    return "".join(out)

