"""Core scoping + action pipeline + output formatting.

Owned by: core (maintained by lead). Agents own the modules this calls into.
"""

import datetime
import os
import sys

import actions
import german
import regexx
import symbols
from langs import LANGS, QueryError


class RuntimeFail(Exception):
    """Printed as 'Error: <message>' on stderr, exit code 1."""

    def __init__(self, message, caused_by=None):
        super().__init__(message)
        self.message = message
        self.caused_by = caused_by  # list of strings, indented progressively


def log_error(msg: str):
    now = datetime.datetime.now(datetime.timezone.utc)
    ts = now.strftime("%Y-%m-%dT%H:%M:%S.") + f"{now.microsecond:06d}Z"
    print(f"[{ts} ERROR srgn] {msg}", file=sys.stderr)


def merge_ranges(ranges):
    """Sort and merge overlapping/adjacent? (not adjacent) ranges."""
    if not ranges:
        return []
    rs = sorted(ranges)
    out = [list(rs[0])]
    for s, e in rs[1:]:
        if s <= out[-1][1]:
            if e > out[-1][1]:
                out[-1][1] = e
        else:
            out.append([s, e])
    return [(s, e) for s, e in out]


def intersect_ranges(a, b):
    """Intersect two sorted merged range lists."""
    out = []
    i = j = 0
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        s = max(s1, s2)
        e = min(e1, e2)
        if s < e:
            out.append((s, e))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return out


def lang_ranges(text: str, opts) -> list:
    """Compute language scope ranges, or None if no language given."""
    if not opts.langs:
        return None
    lang, slot = next(iter(opts.langs.items()))
    module = LANGS[lang][0]
    per_scope = []
    for val in slot["values"]:
        try:
            rs = module.find_ranges(text, val)
        except QueryError:
            raise RuntimeFail(f"Invalid prepared query value: '{val}'")
        per_scope.append(merge_ranges(rs))
    for q in slot["queries"]:
        try:
            rs = module.find_custom_ranges(text, q)
        except QueryError as e:
            raise RuntimeFail(f"Invalid tree-sitter query: {e}")
        per_scope.append(merge_ranges(rs))
    for qf in slot["query_files"]:
        try:
            with open(qf, "r", encoding="utf-8") as f:
                q = f.read()
        except OSError as e:
            raise RuntimeFail(f"Failed reading query file: {e}")
        try:
            rs = module.find_custom_ranges(text, q)
        except QueryError as e:
            raise RuntimeFail(f"Invalid tree-sitter query: {e}")
        per_scope.append(merge_ranges(rs))
    if not per_scope:
        return None
    if opts.join_language_scopes:
        allr = []
        for rs in per_scope:
            allr.extend(rs)
        return merge_ranges(allr)
    acc = per_scope[0]
    for rs in per_scope[1:]:
        acc = intersect_ranges(acc, rs)
    return acc


class Entry:
    __slots__ = ("s", "e", "m")

    def __init__(self, s, e, m=None):
        self.s = s
        self.e = e
        self.m = m


def compute_entries(text: str, opts):
    """Final scope entries: (start, end, regex match or None), char offsets."""
    pattern = opts.scope if opts.scope is not None else ".*"
    try:
        cre = regexx.compile_pattern(pattern, opts.literal)
    except regexx.RegexBuildError as e:
        raise RuntimeFail("Failed building regex", [f"Invalid regex: {e}"])
    lr = lang_ranges(text, opts)
    entries = []
    for m in cre.finditer(text):
        s, e = m.span(0)
        if s == e:
            continue  # empty matches are not in scope (observed)
        if lr is None:
            entries.append(Entry(s, e, m))
        else:
            for cs, ce in intersect_ranges([(s, e)], lr):
                entries.append(Entry(cs, ce, m))
    return entries


def apply_actions(text: str, entries, opts) -> str:
    if not entries:
        return text
    out = []
    prev = 0
    i = 0
    n = len(entries)
    while i < n:
        ent = entries[i]
        s, e = ent.s, ent.e
        if opts.squeeze:
            # collapse run of adjacent entries
            j = i
            while j + 1 < n and entries[j + 1].s == entries[j].e:
                j += 1
            run_end = entries[j].e
            content = text[s:e]  # keep first occurrence
            i = j + 1
            e = run_end  # delete the rest of the run
        else:
            content = text[s:e]
            i += 1
        if opts.delete:
            content = ""
        else:
            if opts.replacement is not None:
                if ent.m is not None:
                    try:
                        content = actions.substitute_template(opts.replacement, ent.m)
                    except actions.ActionError as ex:
                        raise RuntimeFail(f"Error applying: {ex}")
                else:
                    content = opts.replacement
            if opts.german:
                content = german.apply(content, opts.german_naive, opts.german_prefer_original)
            if opts.symbols:
                content = symbols.apply(content, opts.invert)
            if opts.upper:
                content = actions.upper(content)
            if opts.lower:
                content = actions.lower(content)
            if opts.titlecase:
                content = actions.titlecase(content)
            if opts.normalize:
                content = actions.normalize(content)
        out.append(text[prev:s])
        out.append(content)
        prev = e
    out.append(text[prev:])
    return "".join(out)


def is_search_mode(opts) -> bool:
    return bool(opts.langs) and not opts.actions_given


def _line_index(text):
    """Return list of (line_start, line_end_excl_newline) char offsets."""
    lines = []
    start = 0
    for i, ch in enumerate(text):
        if ch == "\n":
            lines.append((start, i))
            start = i + 1
    if start < len(text):
        lines.append((start, len(text)))
    elif not text:
        pass
    return lines


def _byte_offsets(s: str):
    """Map char index -> byte offset for a line string."""
    # build incrementally
    offsets = [0]
    total = 0
    for ch in s:
        total += len(ch.encode("utf-8"))
        offsets.append(total)
    return offsets


def format_line_mode(text: str, entries, opts, path_label: str, tty: bool) -> str:
    """grep-like per-line output. entries are the (original) scope ranges."""
    search = is_search_mode(opts)
    show_numbers = opts.line_numbers or search
    lines = _line_index(text)
    # entries per line
    result_lines = []
    ei = 0
    entries = sorted((e.s, e.e) for e in entries)
    for lineno, (ls, le) in enumerate(lines, start=1):
        # collect intersections
        ranges = []
        for (s, e) in entries:
            if e <= ls:
                continue
            if s > le:
                break if s > le else None
            cs = max(s, ls)
            ce = min(e, le)
            if cs < ce:
                ranges.append((cs - ls, ce - ls))
        if not ranges and (search or opts.only_matching):
            continue
        content = text[ls:le]
        if tty:
            if show_numbers:
                result_lines.append(f"{lineno}:{content}")
            else:
                result_lines.append(content)
        else:
            boff = _byte_offsets(content)
            rstr = ";".join(f"{boff[s]}-{boff[e]}" for s, e in ranges)
            if show_numbers:
                result_lines.append(f"{path_label}:{lineno}:{rstr}:{content}")
            else:
                result_lines.append(f"{path_label}:{rstr}:{content}")
    return "\n".join(result_lines) + ("\n" if result_lines else "")


def process_text(text: str, opts, path_label="(stdin)", tty=False):
    """Returns (stdout_str, exit_code). May raise RuntimeFail."""
    search = is_search_mode(opts)
    if not search and not opts.modifying_actions_given:
        log_error("No actions specified, and not in search mode. Will return input unchanged, if any.")

    entries = compute_entries(text, opts)
    anything = len(entries) > 0

    new_text = apply_actions(text, entries, opts)

    if opts.fail_any and anything:
        raise RuntimeFail("Error applying: Some input was in scope")
    if opts.fail_none and not anything:
        raise RuntimeFail("Error applying: No input was in scope")

    line_mode = search or opts.only_matching or opts.line_numbers
    if line_mode:
        return format_line_mode(new_text, entries, opts, path_label, tty), 0
    return new_text, 0

